css:
:where(.wtyg-map-site_banking_dynasties) *{margin: 0;
            padding: 0;
            box-sizing: border-box;}
:where(.wtyg-map-site_banking_dynasties){font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Helvetica Neue', Arial, sans-serif;
            background: #0a0a0a;
            color: #c4c4c4;
            padding: 0;
            line-height: 1.6;
            font-weight: 300;}
:where(.wtyg-map-site_banking_dynasties) .container{max-width: 1900px;
            margin: 0 auto;
            padding: 40px 30px;}
:where(.wtyg-map-site_banking_dynasties) header{text-align: center;
            padding: 60px 20px 40px;
            margin-bottom: 50px;
            border-bottom: 1px solid #2a2a2a;}
:where(.wtyg-map-site_banking_dynasties) h1{font-size: 2.8em;
            margin-bottom: 12px;
            color: #ffffff;
            font-weight: 200;
            letter-spacing: 2px;
            text-transform: uppercase;}
:where(.wtyg-map-site_banking_dynasties) .subtitle{font-size: 1em;
            color: #808080;
            font-weight: 300;
            letter-spacing: 1px;
            text-transform: uppercase;}
:where(.wtyg-map-site_banking_dynasties) .chart-container{background: #121212;
            border: 1px solid #1a1a1a;
            padding: 40px;
            margin-bottom: 40px;}
:where(.wtyg-map-site_banking_dynasties) h2{color: #ffffff;
            margin-bottom: 30px;
            font-size: 1.4em;
            font-weight: 300;
            letter-spacing: 1.5px;
            text-transform: uppercase;
            border-bottom: 1px solid #2a2a2a;
            padding-bottom: 15px;}
:where(.wtyg-map-site_banking_dynasties) .timeline-svg{width: 100%;
            height: 1200px;
            background: #0a0a0a;
            overflow: visible;}
:where(.wtyg-map-site_banking_dynasties) .era-bg{opacity: 0.03;}
:where(.wtyg-map-site_banking_dynasties) .era-label{font-size: 10px;
            font-weight: 400;
            fill: #505050;
            text-transform: uppercase;
            letter-spacing: 1px;}
:where(.wtyg-map-site_banking_dynasties) .family-line{cursor: pointer;
            transition: all 0.2s ease;}
:where(.wtyg-map-site_banking_dynasties) .family-line:hover{filter: brightness(1.3);}
:where(.wtyg-map-site_banking_dynasties) .family-label{font-size: 10px;
            fill: #c4c4c4;
            font-weight: 400;
            letter-spacing: 0.5px;}
:where(.wtyg-map-site_banking_dynasties) .year-label{font-size: 10px;
            fill: #606060;
            font-weight: 300;}
:where(.wtyg-map-site_banking_dynasties) .axis-line{stroke: #2a2a2a;
            stroke-width: 1;}
:where(.wtyg-map-site_banking_dynasties) .grid-line{stroke: #1a1a1a;
            stroke-width: 1;
            stroke-dasharray: 2,4;}
:where(.wtyg-map-site_banking_dynasties) .peak-glow{filter: drop-shadow(0 0 8px currentColor);}
:where(.wtyg-map-site_banking_dynasties) .legend{display: flex;
            justify-content: center;
            flex-wrap: wrap;
            gap: 30px;
            margin: 30px 0;
            padding: 25px;
            background: #0a0a0a;
            border: 1px solid #1a1a1a;}
:where(.wtyg-map-site_banking_dynasties) .legend-item{display: flex;
            align-items: center;
            gap: 12px;}
:where(.wtyg-map-site_banking_dynasties) .legend-line{width: 40px;
            height: 2px;}
:where(.wtyg-map-site_banking_dynasties) .legend-text{font-size: 11px;
            color: #808080;
            text-transform: uppercase;
            letter-spacing: 0.5px;
            font-weight: 300;}
:where(.wtyg-map-site_banking_dynasties) .stats-grid{display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 2px;
            margin: 0 0 50px 0;
            background: #1a1a1a;}
:where(.wtyg-map-site_banking_dynasties) .stat-card{background: #0a0a0a;
            padding: 35px 25px;
            text-align: center;
            border: 1px solid #1a1a1a;}
:where(.wtyg-map-site_banking_dynasties) .stat-number{font-size: 3.5em;
            color: #ffffff;
            font-weight: 200;}
:where(.wtyg-map-site_banking_dynasties) .stat-label{font-size: 0.75em;
            color: #606060;
            margin-top: 8px;
            text-transform: uppercase;
            letter-spacing: 1px;
            font-weight: 400;}
:where(.wtyg-map-site_banking_dynasties) .tooltip{position: absolute;
            background: #000000;
            border: 1px solid #2a2a2a;
            padding: 20px;
            display: none;
            z-index: 1000;
            max-width: 400px;
            box-shadow: 0 10px 40px rgba(0,0,0,0.9);
            font-size: 12px;}
:where(.wtyg-map-site_banking_dynasties) .tooltip h3{color: #ffffff;
            margin-bottom: 12px;
            font-size: 1.1em;
            font-weight: 400;
            letter-spacing: 1px;}
:where(.wtyg-map-site_banking_dynasties) .tooltip p{margin: 8px 0;
            font-size: 0.9em;
            color: #808080;
            line-height: 1.6;}
:where(.wtyg-map-site_banking_dynasties) .tooltip strong{color: #c4c4c4;
            font-weight: 400;}
:where(.wtyg-map-site_banking_dynasties) canvas{max-height: 500px;}
:where(.wtyg-map-site_banking_dynasties) .dot-start,:where(.wtyg-map-site_banking_dynasties) .dot-end{cursor: pointer;
            transition: all 0.2s ease;}
:where(.wtyg-map-site_banking_dynasties) .dot-start:hover,:where(.wtyg-map-site_banking_dynasties) .dot-end:hover{r: 6;
            filter: brightness(1.5);}
:where(.wtyg-map-site_banking_dynasties) .power-grid{display: grid;
            grid-template-columns: repeat(auto-fit, minmax(500px, 1fr));
            gap: 40px;
            margin-top: 30px;}
:where(.wtyg-map-site_banking_dynasties) .family-card{background: #0a0a0a;
            border: 1px solid #2a2a2a;
            padding: 20px;
            transition: all 0.2s ease;}
:where(.wtyg-map-site_banking_dynasties) .family-card:hover{border-color: #404040;
            background: #0f0f0f;}
:where(.wtyg-map-site_banking_dynasties) .family-card-header{display: flex;
            justify-content: space-between;
            align-items: baseline;
            margin-bottom: 15px;
            padding-bottom: 12px;
            border-bottom: 1px solid #2a2a2a;}
:where(.wtyg-map-site_banking_dynasties) .family-card-title{font-size: 1.1em;
            color: #ffffff;
            font-weight: 300;
            letter-spacing: 1px;}
:where(.wtyg-map-site_banking_dynasties) .family-card-period{font-size: 0.8em;
            color: #606060;
            text-transform: uppercase;
            letter-spacing: 0.5px;}
:where(.wtyg-map-site_banking_dynasties) .city-tags{display: flex;
            flex-wrap: wrap;
            gap: 8px;}
:where(.wtyg-map-site_banking_dynasties) .city-tag{background: #1a1a1a;
            border: 1px solid #2a2a2a;
            padding: 5px 10px;
            font-size: 0.8em;
            color: #808080;
            border-radius: 2px;}
